Get-ChildItem -Path "$androidTestPath\quizgame" -File | ForEach-Object { $content = Get-Content $_.FullName -Raw $content = $content -replace 'package com\.example\.quizgame', 'package com.example.cinequiz' Set-Content "$androidTestPath\cinequiz\$($_.Name)" -Value $content -NoNewline }
Remove-Item -Path "$androidTestPath\quizgame" -Recurse -Force Write-Host " AndroidTest actualizado" -ForegroundColor Green }
Write-Host "" Write-Host "==================================================" -ForegroundColor Cyan Write-Host "Reorganización completada!" -ForegroundColor Green Write-Host "==================================================" -ForegroundColor Cyan Write-Host "" Write-Host "Paquete cambiado de:" -ForegroundColor Yellow Write-Host " com.example.quizgame" -ForegroundColor White Write-Host "a:" -ForegroundColor Yellow Write-Host " com.example.cinequiz" -ForegroundColor White Write-Host "" Write-Host "Ahora sincroniza el proyecto en Android Studio." -ForegroundColor Cyan

pluginManagement {
    repositories {
        google {
            content {
                includeGroupByRegex("com\\.android.*")
                includeGroupByRegex("com\\.google.*")
                includeGroupByRegex("androidx.*")
            }
        }
        mavenCentral()
        gradlePluginPortal()
    }
}
dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        google()
        mavenCentral()
    }
}

rootProject.name = "CineQuiz"
include ':app'

